sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float mask;
uniform float2 maskCenter;
uniform float maskWidth;
uniform float maskHeight;
uniform float sides;
uniform float feather;
float inside(float2 coord) {
    if (mask < 0.5) return 1.0;
    float2 reach = max(float2(maskWidth, maskHeight) * size * 0.5, float2(0.5));
    float2 p = coord - maskCenter * size;
    float unit = min(reach.x, reach.y);
    float d;
    if (mask < 1.5) {
        float2 q = abs(p) - reach;
        d = length(max(q, float2(0.0))) + min(max(q.x, q.y), 0.0);
    } else if (mask < 2.5) {
        d = (length(p / reach) - 1.0) * unit;
    } else {
        float n = clamp(floor(sides + 0.5), 3.0, 12.0);
        float2 u = p / reach;
        float seg = 6.2831853 / n;
        float a = atan(u.x, -u.y);
        float k = (floor(a / seg) + 0.5) * seg;
        d = (length(u) * cos(a - k) - cos(seg * 0.5)) * unit;
    }
    float soft = max(clamp(feather, 0.0, 1.0) * unit, 0.75);
    return 1.0 - smoothstep(-soft, soft, d);
}
half4 main(float2 coord) {
    float4 o = float4(image.eval(coord));
    float m = inside(coord);
    if (m <= 0.0) return half4(o);
    float4 b = float4(blurred.eval(coord));
    float4 r = float4(b.rgb + o.rgb - max(b.rgb * o.a, o.rgb * b.a), b.a + o.a - b.a * o.a);
    return half4(mix(o, r, m));
}
